#include <Arduino.h>
#include <Servo.h>

Servo motor;
int angle = 0;
int direction = 1;
unsigned long lastStep = 0;
const unsigned long stepDelayMs = 15;

void setup() {
  Serial.begin(9600);
  motor.attach(9);
  motor.write(0);
  lastStep = millis();
}

void loop() {
  unsigned long now = millis();
  if (now - lastStep < stepDelayMs) return;
  lastStep = now;

  angle += direction;
  motor.write(angle);

  if (angle == 180) {
    Serial.println(motor.read());
    direction = -1;
  } else if (angle == 0) {
    Serial.println(motor.read());
    direction = 1;
  }
}
